SELECT event_type, CASE WHEN duration_sec >= 487 THEN 'high' WHEN duration_sec >= 212 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, session_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(page))) AS page_values, MAX(event_time) AS latest_event_time FROM web_events WHERE session_id IN (10, 15, 25) AND event_time < '2025-04-01' AND event_type = 'purchase' GROUP BY event_type, CASE WHEN duration_sec >= 487 THEN 'high' WHEN duration_sec >= 212 THEN 'mid' ELSE 'low' END, session_id ORDER BY session_id DESC, event_type, duration_sec_bucket LIMIT 5;
